import torch

def interval_advantage(lo, hi, eps=1e-6):
    # lo/hi: [G] 同一 prompt 下各 rollout 的奖励区间端点
    mid = 0.5 * (lo + hi)
    span = (hi - lo).unsqueeze(0) + (hi - lo).unsqueeze(1)   # [G, G] 总跨度
    pair = (mid.unsqueeze(0) - mid.unsqueeze(1)) / (span + eps)
    pair.fill_diagonal_(0.0)
    return pair.sum(dim=1) / (lo.shape[0] - 1)

def point_degenerate(lo, hi):
    # 区间收缩为点时退化为组内中心化优势
    r = 0.5 * (lo + hi)
    return r - r.mean()

import torch

def grpo_advantage(rewards, use_std=True, eps=1e-6):
    centered = rewards - rewards.mean()
    if use_std:
        return centered / (rewards.std(unbiased=False) + eps)
    return centered                      # Dr.GRPO：只中心化，不除标准差

def collapse_ranges(lo, hi):
    # 区间宽度为零时的点奖励
    r = 0.5 * (lo + hi)
    return r

r = torch.tensor([0.2, 0.8, 0.5])
print(grpo_advantage(r, use_std=False))

import torch

def apply_head_edit(w, directions, alphas, topk=2):
    # w: [D] 奖励头权重；directions: [K, D]；alphas: [K] 编辑幅度
    score = alphas.abs()
    idx = torch.topk(score, k=min(topk, score.numel())).indices
    delta = torch.zeros_like(w)
    for k in idx.tolist():
        delta = delta + alphas[k] * directions[k]
    return w + delta

def edited_score(h, w, directions, alphas, topk=2):
    # h: [D] 奖励模型隐藏表示
    return h @ apply_head_edit(w, directions, alphas, topk)
